"""Domain explanations used by the Word book builder."""

TABLES = {
'provinces': ('Create one shared provincial name rather than repeat it on every school.', {}),
'districts': ('Represent the district level of the geographic hierarchy.', {'provinceId':'Place this district beneath an existing province.'}),
'circuits': ('Represent the circuit through which schools are geographically organized.', {'districtId':'Place the circuit beneath its district.'}),
'schools': ('Keep the institution, geographic placement and initial activation lifecycle in one durable record.', {'circuitId':'Identify the geographic circuit.', 'code':'Provide the school code used during staff and learner lookup; absent before activation.', 'activationCode':'Check the initial school claim; this is sensitive provisioning data.', 'activatedAt':'Record whether and when the one-time school activation occurred.'}),
'grades': ('Represent each supported grade inside a particular school while preserving stable IDs for classes.', {'schoolId':'Keep Grade 11 in this school distinct from Grade 11 elsewhere.', 'number':'Store the academic grade number, constrained to 8 through 12.'}),
'subjects': ('Maintain the platform subject catalogue once so many schools and streams can refer to the same subject.', {'name':'Store the subject label. A normalized unique index also rejects case and whitespace variants.'}),
'streams': ('Let a school name a reusable bundle of subjects.', {'schoolId':'Own the bundle at school level, rather than treating all Science streams as one global record.'}),
'stream_subjects': ('Store the many-to-many membership pairs between school streams and shared subjects.', {'streamId':'Identify the bundle receiving the subject.', 'subjectId':'Identify the shared subject included in the bundle.'}),
'classes': ('Represent one teaching group inside a school grade, with setup allowed to happen in stages.', {'gradeId':'Locate the group in the school through its grade.', 'streamId':'Select the current subject bundle; null allows setup before a stream is chosen.', 'classTeacherId':'Identify the class manager or class teacher, distinct from each subject teacher.', 'name':'Store the normalized class name, unique within this grade.', 'description':'Keep an optional short administrative description.'}),
'class_subjects': ('Give the delivery of a subject in one class its own identity and default teacher.', {'classId':'Identify the receiving class.', 'subjectId':'Identify the shared subject being delivered.', 'personId':'Assign the default subject teacher; null means not yet assigned.', 'active':'Retain the allocation and its history after stream membership changes while hiding inactive teaching allocations.'}),
'class_chapters': ('Attach shared chapters to class-subject delivery and allow chapter-specific teaching responsibility.', {'classSubjectId':'Identify the subject delivery whose curriculum is being linked.', 'chapterId':'Identify the shared chapter.', 'personId':'Store the chapter teacher, including exceptions to the class-subject default.'}),
'people': ('Register school staff independently of whether they have claimed login credentials.', {'title':'Keep the staff form of address used in professional names.', 'firstName':'Identify the person by given name and contribute to initials-based lookup.', 'surname':'Identify and sort the staff register by family name.', 'staffNumber':'Keep the school staff identifier as text, including leading zeros or letters.', 'role':'Distinguish staff responsibilities, defaulting to teacher; principal access uses this field.', 'schoolId':'Associate the staff record with its institution.', 'username':'Allow a unique staff login name after claiming; null before setup.', 'passwordHash':'Store the bcrypt verification hash, never the submitted plaintext password.', 'accountSetUp':'Distinguish a registered staff record from a completed account claim.'}),
'learners': ('Register a learner in the correct school and class before allowing the account to be claimed.', {'firstName':'Keep the given name and contribute to lookup initials.', 'surname':'Keep the family name and support register ordering.', 'admissionNumber':'Keep the school admission identifier as text, unique with schoolId.', 'schoolId':'Identify the institution; consistency with class ownership needs service validation.', 'classId':'Place the learner in the one current class modeled by this schema.', 'username':'Allow a unique learner login name after claiming.', 'passwordHash':'Store the bcrypt credential hash; null before the claim.', 'accountSetUp':'Record that credentials have been established.'}),
'app_managers': ('Represent platform-wide curriculum administrators without inventing a school membership.', {'username':'Provide the unique manager login.', 'passwordHash':'Store the bcrypt credential verification value.', 'active':'Permit manager access to be withdrawn and checked again on protected manager requests.'}),
'curriculum_libraries': ('Maintain the shared subject-and-grade curriculum editing identity and conflict version.', {'subjectId':'Identify the catalogue subject.', 'gradeNumber':'Select the curriculum level independently of a particular school grade row.', 'revision':'Reject saves made from an outdated editor version.', 'updatedAt':'Record publication time when the revision is advanced.'}),
'chapters': ('Group the shared ordered curriculum for one subject and grade.', {'subjectId':'Identify the catalogue subject.', 'gradeNumber':'Choose the academic grade whose shared curriculum this chapter belongs to.', 'name':'Store the chapter label.', 'orderIndex':'Preserve pedagogical order independently of ID or alphabetical sorting.', 'active':'Retire the chapter from current curriculum without breaking historical references.', 'label':'Retain an optional additional label used by older chapter operations.'}),
'topics': ('Add a useful organizational level between a chapter and its smallest teaching concepts.', {'chapterId':'Identify the containing chapter.', 'name':'Store the topic heading.', 'orderIndex':'Preserve topic order within the chapter.', 'active':'Retire a topic without deleting referenced concepts.'}),
'concepts': ('Give the smallest teaching unit stable identity for planning, coverage, homework and feedback.', {'chapterId':'Identify the chapter and participate in the composite topic-parent integrity rule.', 'topicId':'Identify the topic; the composite foreign key also requires that topic to be in chapterId.', 'name':'Store the human-readable teaching unit.', 'orderIndex':'Specify concept order within its topic.', 'active':'Retain historical identity after removal from current curriculum.', 'isCustom':'Distinguish teacher additions from platform curriculum entries.', 'classSubjectId':'Scope a teacher custom concept to its class delivery rather than all schools.'}),
'lessons': ('Record a dated teaching occasion separately from the reusable curriculum.', {'chapterId':'Identify the chapter being planned or confirmed.', 'classSubjectId':'Identify the class and subject receiving this lesson.', 'date':'Store the lesson calendar date rather than a clock time.', 'status':'Distinguish planned intent from confirmed teaching; defaults to planned.'}),
'lesson_concepts': ('Represent the many-to-many relationship between lesson occasions and reusable concepts.', {'lessonId':'Identify the teaching occasion.', 'conceptId':'Identify a concept included on that occasion.'}),
'homework': ('Publish one homework set per lesson with a due time and memorandum release policy.', {'lessonId':'Identify the lesson and enforce at most one homework set through uniqueness.', 'dueDate':'Specify the deadline including time of day.', 'memoReleaseType':'Choose immediate, due-date or custom-time release.', 'memoReleaseAt':'Supply the optional time needed for custom release.'}),
'questions': ('Keep individual ordered questions and their concept links inside a homework set.', {'homeworkId':'Identify the homework set.', 'conceptId':'Keep the tested learning unit explicit for feedback and generation.', 'orderIndex':'Preserve the teacher-approved question sequence.', 'body':'Store the editable question text.', 'memo':'Store the optional worked memorandum, which may be added or corrected later.'}),
'lesson_preview_feedback': ('Represent one learner reaction to a concept before a particular lesson.', {'learnerId':'Identify the responding learner for uniqueness and ownership checks.', 'conceptId':'Identify the concept being previewed.', 'lessonId':'Distinguish preview occasions when the same concept returns.', 'reaction':'Store the preview reaction validated by the route.', 'isAnonymous':'Control intended presentation of identity; the database still keeps learnerId.'}),
'lesson_feedback': ('Represent the learner reaction to a concept actually associated with a specific teaching occasion.', {'learnerID':'Identify the responding learner; this TypeScript property uses capital ID while SQL uses learner_id.', 'lessonConceptId':'Target the lesson-concept occurrence, not merely the reusable concept.', 'reaction':'Store understood, not_sure or didnt_understand through the route schema.', 'isAnonymous':'Express the presentation preference while retaining internal learner identity.'}),
'question_feedback': ('Track work and response at the individual homework-question level.', {'learnerId':'Identify the learner for the one-current-response pair.', 'questionId':'Identify the particular question.', 'isDone':'Record completion independently of understanding.', 'memoRevealed':'Record a reported reveal event; it does not itself enforce release access.', 'reaction':'Allow a later understanding response, absent before one is supplied.', 'isAnonymous':'Keep the presentation preference separate from internal identity.'}),
'refresh_tokens': ('Support longer browser sessions while keeping only hashes of random refresh credentials.', {'tokenHash':'Store a unique SHA-256 digest rather than the raw bearer credential.', 'accountType':'Select the account table associated with accountId.', 'accountId':'Identify the account within the selected type; this polymorphic reference has no single foreign key.', 'schoolId':'Retain school scope for school accounts; null supports platform managers.', 'expiresAt':'Reject refresh after the configured lifetime.'}),
'announcements': ('Keep school messages and target a whole school or a selected audience group.', {'schoolId':'Identify the institution publishing the message.', 'createdBy':'Identify the staff author.', 'title':'Supply the compact message heading.', 'body':'Store the message content.', 'audienceType':'Select all, grade, class or stream.', 'audienceId':'Identify the selected target; null for all, with target-type consistency enforced by services rather than a single foreign key.'}),
}

