CONFIG_NOTES = {
'package.json':'Declare executable scripts and direct dependencies. Explain a change here together with its lockfile impact; a declared package is not proof every feature uses it.',
'tsconfig.json':'Define compiler checking, module handling and source boundaries. The frontend delegates emitted bundles to Next; the backend emits dist from src.',
'.gitignore':'Prevent ordinary tracking of local dependencies, configuration and generated output. It does not retroactively remove already committed files.',
'drizzle.config.ts':'Connect typed schema discovery and migration output to PostgreSQL. DATABASE_URL must be available to this process; the file itself does not load dotenv.',
'next.config.ts':'Wrap Next configuration with next-pwa and disable its service worker during development. Production behavior needs a real compatibility/build check.',
'postcss.config.mjs':'Connect Tailwind v4 processing to the CSS build pipeline.',
'eslint.config.mjs':'Compose the installed Next performance and TypeScript lint rules and exclude generated output.',
'public/manifest.json':'Describe installable-web-app identity, launch URL, display preference and icon paths. It does not supply offline data synchronization.',
}

GLOSSARY = {
'API':'A defined way for one program to request operations from another; here the browser calls Express HTTP routes.',
'Authentication':'Verifying which account supplied a request, here through signed bearer tokens.',
'Authorization':'Deciding whether that account may act on this school, allocation, lesson or question.',
'Component':'A React function that describes part of the interface from props and state.',
'Constraint':'A database rule that rejects invalid rows even when a particular screen is bypassed.',
'Curriculum retirement':'Setting active to false so current lists change while old lesson references remain valid.',
'Dependency injection':'Passing a database or request function into a service so tests can control external behavior.',
'Foreign key':'A reference whose database rule requires a matching row in another table.',
'Hydration':'Attaching client-side React behavior to initially rendered browser markup.',
'Identity':'A stable reference such as a database ID, distinct from a label or current position.',
'Index':'A database structure used for lookup and, for unique indexes, enforcing distinct values.',
'JSON':'A text representation of objects, arrays and primitive values used in API request/response bodies.',
'JSX':'Element syntax in JavaScript or TypeScript that describes React output.',
'Middleware':'A request-pipeline function that can reject, annotate or pass a request to the next handler.',
'Migration':'An ordered, versioned database change applied to move an existing database forward.',
'ORM':'A library connecting application code to relational queries and schema definitions; this app uses Drizzle.',
'Primary key':'The stable unique identifier of a database row.',
'Promise':'A JavaScript object representing a result that will become available or fail later.',
'Props':'Values supplied to a React component by its parent.',
'Ref':'Mutable React-held storage that does not itself cause rendering when changed.',
'Revision':'A version marker; backend curriculum revisions detect stale saves, while local UI revisions force reloads.',
'Route':'A method and address handled by the backend, or a URL segment served by a Next page.',
'Schema':'A description of data structure; database schemas and Zod input schemas enforce different boundaries.',
'Seed':'Initial reference or sample data inserted separately from the database structure.',
'State':'Component-held values whose updates change the rendered interface.',
'Transaction':'A group of database operations that commits together or rolls back together.',
'Upsert':'Insert a new record or update the matching current record; concurrency behavior depends on its implementation.',
}
